package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.apache.commons.math3.exception.OutOfRangeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class ElitisticListPopulation_setElitismRate_TriageGen2Test {

    private ElitisticListPopulation population;
    private final int populationLimit = 10;
    private final double initialElitismRate = 0.1;

    @Before
    public void setUp() {
        population = new ElitisticListPopulation(populationLimit, initialElitismRate);
    }

    @Test
    public void testSetElitismRate_ValidValue_LowerBound() {
        double validRate = 0.0;
        population.setElitismRate(validRate);
        Assert.assertEquals("Elitism rate should be 0.0", validRate, population.getElitismRate(), 1e-9);
    }










}

