        population = new ElitisticListPopulation(populationLimit, initialElitismRate);
    }











    @Test
    public void testConstructor_And_GetElitismRate() {
        // Testing the constructor integration with getter to ensure state is set correctly
        ElitisticListPopulation popWithChromosomes = new ElitisticListPopulation(new ArrayList<Chromosome>(), 5, 0.2);
